def backfill_historical_course_group_assignments(apps, schema_editor):
    Enrollment = apps.get_model("learning", "CourseEnrollment")
    Cohort = apps.get_model("learning", "LearningCohort")
    Assignment = apps.get_model("learning", "EnrollmentCohortAssignment")
    RosterEvent = apps.get_model("learning", "RosterEvent")
    windows = {
        cohort_id: (starts_at, ends_at)
        for cohort_id, starts_at, ends_at in Cohort.objects.values_list(
            "id", "access_starts_at", "access_ends_at"
        )
    }
    for enrollment in Enrollment.objects.exclude(cohort__isnull=True).iterator():
        starts_at, ends_at = windows[enrollment.cohort_id]
        window_mode = (
            "inherit"
            if (enrollment.access_starts_at, enrollment.access_ends_at)
            == (starts_at, ends_at)
            else "individual"
        )
        Enrollment.objects.filter(pk=enrollment.pk).update(
            access_provenance="legacy_migration",
            access_window_mode=window_mode,
        )
        Assignment.objects.create(
            enrollment_id=enrollment.pk,
            cohort_id=enrollment.cohort_id,
            source="legacy_migration",
            reason="Migración compatible desde CourseEnrollment.cohort",
            started_by_id=enrollment.created_by_id,
            started_at=enrollment.created_at,
        )
        RosterEvent.objects.create(
            organization_id=enrollment.organization_id,
            cohort_id=enrollment.cohort_id,
            event_type="legacy_backfilled",
            actor_id=enrollment.created_by_id,
            occurred_at=enrollment.created_at,
            details={"enrollment_id": str(enrollment.pk)},
        )


