def remove_historical_course_group_integrity(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(
            """
            DROP TRIGGER IF EXISTS learning_validate_active_cohort_assignment_trigger
              ON learning_enrollmentcohortassignment;
            DROP TRIGGER IF EXISTS learning_validate_cohort_staff_assignment_trigger
              ON learning_cohortstaffassignment;
            DROP TRIGGER IF EXISTS learning_immutable_cohort_assignment_trigger
              ON learning_enrollmentcohortassignment;
            DROP TRIGGER IF EXISTS learning_immutable_cohort_staff_trigger
              ON learning_cohortstaffassignment;
            DROP TRIGGER IF EXISTS learning_immutable_roster_event_trigger
              ON learning_rosterevent;
            DROP FUNCTION IF EXISTS learning_validate_active_cohort_assignment();
            DROP FUNCTION IF EXISTS learning_validate_cohort_staff_assignment();
            DROP FUNCTION IF EXISTS learning_prevent_closed_assignment_mutation();
            DROP FUNCTION IF EXISTS learning_prevent_roster_event_mutation();
            """
        )


